customCSS:
.t, .history { color: #616e88; }
.join { color: #a3be8c; }
.part, .quit { color: #616e88; }
.kick, .error { color: #bf616a; }
.notice { color: #ebcb8b; }
.action { color: #b48ead; }
.mode, .nick, .topic, .server { color: #88c0d0; }
.highlight { color: #d8dee9; background-color: #434c5e; border-left: 3px solid #b48ead; padding-left: 8px; }
.reply { color: #616e88; border-left: 2px solid #81a1c1; padding-left: 6px; }
.oper { color: #2e3440; background-color: #ebcb8b; }
.reactions { color: #81a1c1; background-color: #3b4252; }
.card { background-color: #3b4252; border-color: #616e88; }
.card-title { color: #81a1c1; }
.card-desc { color: #616e88; }
.daychange { color: #616e88; border-color: #3b4252; }
